import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { GitInfo } from '../types'
import { detailParts, isClean, mentionsGit, parseStatus } from './git'

const info = atom({ plugin: 'cm-git-branch', key: 'info' } as const, null)

/** Reads the work tree's status in the session's folder and stores it for the band. */
async function refresh($: EngineInterface): Promise<void> {
  const cwd = await $.session.cwd()
  let next: GitInfo | null = null
  try {
    const status = await $.process.run(['git', 'status', '--porcelain=v1', '-b'], { cwd, timeoutMs: 10_000 })
    next = status.exitCode === 0 ? parseStatus(status.stdout) : null
    if (next?.isDetached === true) {
      const sha = await $.process.run(['git', 'rev-parse', '--short', 'HEAD'], { cwd, timeoutMs: 10_000 })
      if (sha.exitCode === 0 && sha.stdout.trim() !== '') next.branch = sha.stdout.trim()
    }
  } catch {
    // git missing or too slow: show nothing rather than a stale branch.
    next = null
  }
  await update($, info, () => next)
}

export const register: Register = (on, options) => {
  const intervalMs = Math.max(2_000, typeof options.intervalMs === 'number' ? options.intervalMs : 15_000)
  const band = {
    showAheadBehind: options.showAheadBehind !== false,
    hideWhenClean: options.hideWhenClean === true,
  }

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await refresh($)
    $.clock.every(intervalMs, () => {
      refresh($).catch(() => undefined)
    })
    return started
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined) await refresh($)
    return result
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    if (mentionsGit(e.command)) await refresh($)
    return ran
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const current = await read($, info)
    if (e.props.hasSurvey || current === null || (band.hideWhenClean && isClean(current))) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const name = current.isDetached ? `${current.branch} (detached)` : current.branch

    return (
      <Box key="git-branch" flexDirection="row">
        <Text dimColor>⎇ </Text>
        <Text bold color="cyan" wrap="truncate-end">
          {name}
        </Text>
        <Text dimColor wrap="truncate-end">
          {' · ' + detailParts(current, band).join(' · ')}
        </Text>
      </Box>
    )
  })
}

