/**
 * Pure helpers for cm-git-branch: parse `git status --porcelain=v1 -b` and
 * format the band's line. No `$`, so they are unit-tested directly.
 */
import type { GitInfo } from '../types'

/**
 * Reads the porcelain v1 output with its `## ` branch header:
 *   ## main...origin/main [ahead 1, behind 2]
 *   ## No commits yet on main
 *   ## HEAD (no branch)
 * followed by one line per changed path.
 */
export function parseStatus(stdout: string): GitInfo | null {
  const lines = stdout.split('\n').filter(line => line !== '')
  const header = lines[0]
  if (header === undefined || !header.startsWith('## ')) return null
  const changed = lines.length - 1
  const head = header.slice(3)

  if (head.startsWith('HEAD (no branch)')) {
    return { branch: 'HEAD', isDetached: true, ahead: 0, behind: 0, changed }
  }

  const initial = /^(?:No commits yet on|Initial commit on) (.+)$/.exec(head)
  if (initial?.[1] !== undefined) {
    return { branch: initial[1], isDetached: false, ahead: 0, behind: 0, changed }
  }

  const match = /^(.+?)(?:\.\.\.(\S+))?(?: \[(.*)\])?$/.exec(head)
  const branch = match?.[1] ?? head
  const upstream = match?.[2]
  const track = match?.[3] ?? ''
  const ahead = Number(/ahead (\d+)/.exec(track)?.[1] ?? 0)
  const behind = Number(/behind (\d+)/.exec(track)?.[1] ?? 0)
  const info: GitInfo = { branch, isDetached: false, ahead, behind, changed }
  if (upstream !== undefined) info.upstream = upstream
  return info
}

export type BandOptions = { showAheadBehind: boolean; hideWhenClean: boolean }

/** Whether the band has nothing worth showing under `hideWhenClean`. */
export function isClean(info: GitInfo): boolean {
  return info.changed === 0 && info.ahead === 0 && info.behind === 0
}

/** The parts after the branch name: `3 changed`, `↑1 ↓0`. */
export function detailParts(info: GitInfo, options: BandOptions): string[] {
  const parts = [info.changed === 0 ? 'clean' : `${info.changed} changed`]
  if (options.showAheadBehind && info.upstream !== undefined) {
    parts.push(`↑${info.ahead} ↓${info.behind}`)
  }
  return parts
}

/** The whole line as text: `⎇ main · 3 changed · ↑1 ↓0`. */
export function formatLine(info: GitInfo, options: BandOptions): string {
  const name = info.isDetached ? `${info.branch} (detached)` : info.branch
  return [`⎇ ${name}`, ...detailParts(info, options)].join(' · ')
}

/** True for a Bash command that runs git (and so may move HEAD or the index). */
export function mentionsGit(command: string): boolean {
  return /(^|[\s;&|(`])git(\s|$)/.test(command) || /\bgh\s+pr\s+(checkout|merge)\b/.test(command)
}

