/** What the band shows: one reading of `git status --porcelain=v1 -b`. */
export type GitInfo = {
  /** The branch name, or the short commit id when HEAD is detached. */
  branch: string
  isDetached: boolean
  /** The upstream (`origin/main`), when the branch tracks one. */
  upstream?: string
  ahead: number
  behind: number
  /** Changed, staged and untracked paths together. */
  changed: number
}

declare module 'claude-code' {
  interface PluginState {
    'cm-git-branch': {
      /** null while the session's folder is not inside a git work tree. */
      info: GitInfo | null
    }
  }
}
